<?php
/**
 * Font files in the uploads area.
 *
 * @package sw-sliderman
 */

declare(strict_types=1);

namespace SW\Slider\Fonts;

use SW\Slider\Infrastructure\UploadPaths;

/**
 * Stores installations below `uploads/sw-sliderman/fonts/<content hash>/`.
 *
 * Temporary directories (`fonts/.tmp-<random>`) live next to their target so the activation is a
 * same-filesystem rename. Names are generated by the plugin only; deletion is limited to
 * directories matching the plugin's own patterns.
 */
final class UploadsFontStorage implements FontStorage {

	private const TEMP_PREFIX = '.tmp-';

	private function fonts_dir(): string {
		return UploadPaths::base_dir() . '/fonts';
	}

	public function create_temp(): string {
		$temp = $this->fonts_dir() . '/' . self::TEMP_PREFIX . strtolower( wp_generate_password( 16, false ) );
		if ( ! UploadPaths::ensure_dir( $temp ) ) {
			throw new FontError( 'sws_font_storage', 'Cannot create the font directory.' );
		}
		return $temp;
	}

	private function is_own_temp( string $temp ): bool {
		return dirname( $temp ) === $this->fonts_dir() && 1 === preg_match( '/\A\.tmp-[a-z0-9]{16}\z/', basename( $temp ) );
	}

	public function write( string $temp, string $name, string $bytes ): void {
		if ( ! $this->is_own_temp( $temp ) || 1 !== preg_match( '/\A(?:[a-f0-9]{64}\.woff2|font\.css|LICENSE\.txt)\z/', $name ) ) {
			throw new FontError( 'sws_font_storage', 'Unexpected file name.' );
		}
		// phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_file_put_contents -- own temporary directory below uploads.
		if ( false === file_put_contents( $temp . '/' . $name, $bytes, LOCK_EX ) ) {
			throw new FontError( 'sws_font_storage', 'Cannot write a font file.' );
		}
	}

	public function activate( string $temp, string $relative_dir ): bool {
		$target = UploadPaths::path( $relative_dir );
		if ( ! $this->is_own_temp( $temp ) || null === $target ) {
			throw new FontError( 'sws_font_storage', 'Unexpected directory.' );
		}
		if ( file_exists( $target ) ) {
			return false;
		}
		// phpcs:ignore WordPress.WP.AlternativeFunctions.rename_rename -- atomic activation within one directory.
		if ( ! rename( $temp, $target ) ) {
			throw new FontError( 'sws_font_storage', 'Cannot activate the font directory.' );
		}
		return true;
	}

	public function discard( string $temp ): void {
		if ( $this->is_own_temp( $temp ) ) {
			$this->remove_tree( $temp );
		}
	}

	public function remove( string $relative_dir ): void {
		$target = UploadPaths::path( $relative_dir );
		if ( null !== $target && 1 === preg_match( '#\Afonts/[a-f0-9]{24}\z#', $relative_dir ) ) {
			$this->remove_tree( $target );
		}
	}

	public function exists( string $relative_dir ): bool {
		$target = UploadPaths::path( $relative_dir );
		return null !== $target && is_file( $target . '/font.css' );
	}

	public function verify_file( string $relative_dir, string $name, string $sha256 ): bool {
		if ( 1 !== preg_match( '/^[a-zA-Z0-9._-]+$/D', $name ) || str_contains( $name, '..' ) ) {
			return false; }
		$path = UploadPaths::path( $relative_dir . '/' . $name );
		return null !== $path && is_readable( $path ) && is_file( $path ) && hash_equals( $sha256, (string) hash_file( 'sha256', $path ) );
	}

	/** Removes the plain files of one directory level and the directory itself. */
	private function remove_tree( string $dir ): void {
		if ( ! is_dir( $dir ) || is_link( $dir ) ) {
			return;
		}
		foreach ( (array) scandir( $dir ) as $entry ) {
			$path = $dir . '/' . $entry;
			if ( '.' !== $entry && '..' !== $entry && is_file( $path ) && ! is_link( $path ) ) {
				wp_delete_file( $path );
			}
		}
		// phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_rmdir -- own, now empty directory.
		rmdir( $dir );
	}
}
